"use client";

import * as React from "react";
import type { FitAddon } from "@xterm/addon-fit";
import type { ITerminalOptions, ITheme, Terminal as XTerm } from "@xterm/xterm";

import { FrameScope, useInFrame } from "../lib/frame-context";
import { cn } from "../lib/utils";
import { useTheme } from "../scope";

import { Button } from "./button";
import { Icon, type IconSource } from "./icon";
import { MiddleTruncate } from "./middle-truncate";
import { Spinner } from "./spinner";

import frame from "./frame.module.css";
import styles from "./terminal.module.css";

export type TerminalStatus = "connecting" | "connected" | "disconnected" | "error";

export type TerminalHandle = {
  /** Writes output from the session. Writes made before xterm finishes loading are queued. */
  write: (data: string | Uint8Array) => void;
  clear: () => void;
  reset: () => void;
  focus: () => void;
  fit: () => void;
};

export type TerminalProps = Omit<
  React.ComponentPropsWithoutRef<"section">,
  "children" | "onResize" | "onError"
> & {
  /** The connection, such as the account or host name. A string label truncates in the middle. */
  label: React.ReactNode;
  icon?: IconSource;
  status: TerminalStatus;
  /** Why the session ended or failed, shown over the screen while disconnected or in error. */
  message?: React.ReactNode;
  /** Shows a retry button while disconnected or in error. */
  onRetry?: () => void;
  retryLabel?: string;
  /** Controls at the end of the header, such as Disconnect. */
  actions?: React.ReactNode;
  /** Keystrokes and pasted text, to send to the remote shell. */
  onData?: (data: string) => void;
  /** The size once xterm mounts and after every fit that changes it, to send to the remote PTY. */
  onResize?: (size: { cols: number; rows: number }) => void;
  /** The xterm instance once it has mounted, to load addons such as xterm-readline or web links. */
  onReady?: (terminal: XTerm) => void;
  /** Passed to xterm when it mounts. Theme and font come from the Cipher tokens. */
  options?: Omit<ITerminalOptions, "theme" | "fontFamily" | "fontSize">;
  ref?: React.Ref<TerminalHandle>;
};

const statusWords: Record<TerminalStatus, string> = {
  connecting: "Connecting",
  connected: "Connected",
  disconnected: "Disconnected",
  error: "Connection failed"
};

const themeTokens: Partial<Record<keyof ITheme, string>> = {
  background: "surface",
  foreground: "ink",
  cursor: "mark",
  cursorAccent: "surface",
  selectionBackground: "selected-surface",
  scrollbarSliderBackground: "scroll-thumb",
  scrollbarSliderHoverBackground: "scroll-thumb-hover",
  scrollbarSliderActiveBackground: "scroll-thumb-hover",
  black: "ansi-black",
  red: "ansi-red",
  green: "ansi-green",
  yellow: "ansi-yellow",
  blue: "ansi-blue",
  magenta: "ansi-magenta",
  cyan: "ansi-cyan",
  white: "ansi-white",
  brightBlack: "ansi-bright-black",
  brightRed: "ansi-bright-red",
  brightGreen: "ansi-bright-green",
  brightYellow: "ansi-bright-yellow",
  brightBlue: "ansi-bright-blue",
  brightMagenta: "ansi-bright-magenta",
  brightCyan: "ansi-bright-cyan",
  brightWhite: "ansi-bright-white"
};

// xterm parses only hex and rgb colors, and the tokens hold var() and color-mix(), so each one is
// resolved by the browser and read back as a pixel.
function readTheme(host: HTMLElement): ITheme {
  const probe = document.createElement("span");
  host.appendChild(probe);
  const context = document.createElement("canvas").getContext("2d", { willReadFrequently: true });
  const theme = Object.fromEntries(
    Object.entries(themeTokens).map(([key, token]) => {
      probe.style.color = `var(--cipher-${token})`;
      const color = getComputedStyle(probe).color;
      if (!context) return [key, color];
      context.clearRect(0, 0, 1, 1);
      context.fillStyle = color;
      context.fillRect(0, 0, 1, 1);
      const [r, g, b, a] = context.getImageData(0, 0, 1, 1).data;
      return [key, `rgba(${r}, ${g}, ${b}, ${(a / 255).toFixed(3)})`];
    })
  );
  probe.remove();
  return theme;
}

export function Terminal({
  label,
  icon = "terminal",
  status,
  message,
  onRetry,
  retryLabel,
  actions,
  onData,
  onResize,
  onReady,
  options,
  className,
  ref,
  ...props
}: TerminalProps) {
  const hostRef = React.useRef<HTMLDivElement>(null);
  const retryRef = React.useRef<HTMLButtonElement>(null);
  const terminalRef = React.useRef<XTerm | null>(null);
  const fitRef = React.useRef<FitAddon | null>(null);
  const pending = React.useRef<(string | Uint8Array)[] | null>([]);
  const latest = React.useRef({ onData, onResize, onReady, options });
  latest.current = { onData, onResize, onReady, options };
  const [load, setLoad] = React.useState<"loading" | "ready" | "failed">("loading");
  const theme = useTheme();
  const embedded = useInFrame("Terminal");
  const labelText = typeof label === "string" ? label : undefined;
  const labelId = React.useId();
  const ended = status === "disconnected" || status === "error" || load === "failed";

  React.useImperativeHandle(
    ref,
    () => ({
      write: (data) => {
        if (terminalRef.current) terminalRef.current.write(data);
        else pending.current?.push(data);
      },
      clear: () => {
        pending.current?.splice(0);
        terminalRef.current?.clear();
      },
      reset: () => {
        pending.current?.splice(0);
        terminalRef.current?.reset();
      },
      focus: () => terminalRef.current?.focus(),
      fit: () => fitRef.current?.fit()
    }),
    []
  );

  React.useEffect(() => {
    const host = hostRef.current;
    if (!host) return undefined;
    let disposed = false;
    let teardown = () => {};
    const style = getComputedStyle(host);
    Promise.all([
      import("@xterm/xterm"),
      import("@xterm/addon-fit"),
      import("@xterm/xterm/css/xterm.css"),
      document.fonts?.load(`${style.fontSize} ${style.fontFamily}`).catch(() => undefined)
    ]).then(
      ([xterm, fit]) => {
        if (disposed) return;
        const terminal = new xterm.Terminal({
          cursorBlink: true,
          scrollback: 10000,
          minimumContrastRatio: 4.5,
          ...latest.current.options,
          fontFamily: style.fontFamily,
          fontSize: parseFloat(style.fontSize),
          theme: readTheme(host)
        });
        const fitAddon = new fit.FitAddon();
        terminal.loadAddon(fitAddon);
        const subscriptions = [
          terminal.onData((data) => latest.current.onData?.(data)),
          terminal.onResize((size) => latest.current.onResize?.(size))
        ];
        terminal.open(host);
        fitAddon.fit();
        latest.current.onResize?.({ cols: terminal.cols, rows: terminal.rows });
        const observer = new ResizeObserver(() => fitAddon.fit());
        observer.observe(host);
        terminalRef.current = terminal;
        fitRef.current = fitAddon;
        latest.current.onReady?.(terminal);
        pending.current?.splice(0).forEach((data) => terminal.write(data));
        setLoad("ready");
        teardown = () => {
          observer.disconnect();
          subscriptions.forEach((subscription) => subscription.dispose());
          terminalRef.current = null;
          fitRef.current = null;
          terminal.dispose();
        };
      },
      (error: unknown) => {
        if (disposed) return;
        pending.current = null;
        console.error(
          "Terminal needs the optional peer dependencies @xterm/xterm and @xterm/addon-fit.",
          error
        );
        setLoad("failed");
      }
    );
    return () => {
      disposed = true;
      teardown();
    };
  }, []);

  React.useEffect(() => {
    const host = hostRef.current;
    if (load !== "ready" || !host || !terminalRef.current) return;
    terminalRef.current.options.theme = readTheme(host);
  }, [load, theme]);

  React.useEffect(() => {
    const terminal = terminalRef.current;
    if (load !== "ready" || !terminal) return;
    terminal.options.disableStdin = ended || Boolean(latest.current.options?.disableStdin);
    if (status === "connected") terminal.focus();
    else if (ended && hostRef.current?.contains(document.activeElement)) retryRef.current?.focus();
  }, [load, status, ended]);

  const tone = load === "failed" ? "error" : status;
  const overlayTitle =
    load === "failed"
      ? "Terminal could not load"
      : status === "error"
        ? "Connection failed"
        : "Session ended";

  return (
    <section
      data-slot="terminal"
      data-status={tone}
      data-embedded={embedded || undefined}
      aria-label={labelText}
      aria-labelledby={labelText ? undefined : labelId}
      className={cn(!embedded && frame.frame, styles.terminal, className)}
      {...props}
    >
      <FrameScope framed>
        <div className={cn(frame.frameHead, styles.header)}>
          <div id={labelId} className={styles.identity}>
            <Icon icon={icon} />
            {labelText ? (
              <MiddleTruncate keepEnd={16} className={styles.label}>
                {labelText}
              </MiddleTruncate>
            ) : (
              label
            )}
          </div>
          <span role="status" className={styles.status} data-tone={tone}>
            {tone === "connecting" ? <Spinner /> : <span aria-hidden className={styles.dot} />}
            {load === "failed" ? statusWords.error : statusWords[status]}
          </span>
          {actions && <div className={styles.actions}>{actions}</div>}
        </div>
        <div className={cn(frame.frameInset, styles.body)}>
          <div ref={hostRef} className={styles.screen} />
          {ended && (
            <div className={styles.overlay} role={tone === "error" ? "alert" : undefined}>
              <p className={styles.overlayTitle}>{overlayTitle}</p>
              {message && load !== "failed" && <p className={styles.message}>{message}</p>}
              {onRetry && load !== "failed" && (
                <Button ref={retryRef} variant="outline" icon="sync" onClick={onRetry}>
                  {retryLabel ?? (status === "error" ? "Retry" : "Reconnect")}
                </Button>
              )}
            </div>
          )}
        </div>
      </FrameScope>
    </section>
  );
}
Terminal.displayName = "Terminal";

.frame {
  --cipher-frame-pad: var(--cipher-space-3);
  --cipher-frame-inner-radius: 0;
  min-width: 0;
  padding: var(--cipher-frame-pad);
  background: var(--cipher-tint);
  border: 0;
  border-radius: 0;
}
.frame[data-frame-head] {
  padding-top: 0;
}
.frame[data-frame-foot] {
  padding-bottom: 0;
}
.frameFoot[hidden] {
  display: none;
}
.frameHead,
.frameFoot.frameFoot,
.frameToolbar {
  --cipher-size-control-default: var(--cipher-size-control-band);
}
/* A band holds one control height: an explicit size on a band action only skews it against its
   neighbours, so every action takes the band tier. Slot buttons inside a field keep their own size. */
:is(.frameHead, .frameFoot.frameFoot, .frameToolbar)
  [data-cipher-button]:not(:is([data-field-box], [data-slot="input-group"]) *) {
  --cipher-action-requested-height: var(--cipher-size-control-band);
  --cipher-button-icon-size: var(--cipher-size-icon-sm);
}
:is(.frameHead, .frameFoot.frameFoot, .frameToolbar)
  [data-cipher-button]:is([data-size="xs"], [data-size="md"], [data-size="lg"]):not(
    :is([data-field-box], [data-slot="input-group"]) *
  ) {
  --cipher-action-font-size: var(--cipher-type-label-font-size);
  --cipher-action-line-height: var(--cipher-type-label-line-height);
  --cipher-action-inset: var(--cipher-space-control-inline-sm);
  --cipher-action-icon-size: var(--cipher-size-icon-label);
}
:is(.frameHead, .frameFoot.frameFoot, .frameToolbar)
  [data-cipher-button][data-icon-only]:is([data-size="xs"], [data-size="md"], [data-size="lg"]):not(
    :is([data-field-box], [data-slot="input-group"]) *
  ) {
  --cipher-action-icon-size: var(--cipher-size-icon-sm);
}
:is(.frameHead, .frameFoot.frameFoot, .frameToolbar)
  [data-cipher-button][data-size="icon-xs"]:not(:is([data-field-box], [data-slot="input-group"]) *) {
  --cipher-action-icon-size: var(--cipher-size-icon-sm);
}
.frameFoot.frameFoot {
  min-height: var(--cipher-space-40);
  padding: var(--cipher-space-6) var(--cipher-space-frame-inline);
  padding-inline-start: calc(var(--cipher-space-frame-inline) + var(--cipher-space-frame-title-inline));
  border: 0;
  color: var(--cipher-muted);
  font-variant-numeric: tabular-nums;
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  line-height: var(--cipher-type-caption-line-height);
}
.frameHead {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  align-content: center;
  justify-content: space-between;
  gap: var(--cipher-space-4) var(--cipher-space-12);
  min-height: var(--cipher-space-40);
  padding: var(--cipher-space-4) var(--cipher-space-frame-inline);
  min-width: 0;
}
.frameHead[data-select] {
  padding-inline-start: calc(var(--cipher-space-frame-inline) + var(--cipher-space-frame-title-inline));
}
.frameHead[data-select] > .frameTitle,
.frameHead[data-select] > * > .frameTitle:first-child {
  margin-inline-start: 0;
}
.frameTitle {
  flex: 1 1 var(--cipher-size-cell-min);
  min-width: 0;
  margin-inline-start: var(--cipher-space-frame-title-inline);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--cipher-muted);
  text-transform: uppercase;
  font-family: var(--cipher-type-eyebrow-font-family);
  font-size: var(--cipher-type-eyebrow-font-size);
  line-height: var(--cipher-type-eyebrow-line-height);
  font-weight: var(--cipher-type-eyebrow-font-weight);
  letter-spacing: var(--cipher-type-eyebrow-letter-spacing);
}
.frameTitle[data-hint] {
  padding: var(--cipher-focus-clearance);
  margin: calc(-1 * var(--cipher-focus-clearance));
  margin-inline-start: calc(var(--cipher-space-frame-title-inline) - var(--cipher-focus-clearance));
}
.frameTitleHint {
  text-decoration-line: underline;
  text-decoration-style: dotted;
  text-decoration-color: var(--cipher-faint);
  text-decoration-thickness: var(--cipher-size-control-border);
  text-underline-offset: var(--cipher-space-3);
}
.frameAction {
  flex: none;
  margin-inline-start: 0;
  display: flex;
  align-items: center;
  gap: var(--cipher-space-8);
  color: var(--cipher-text2);
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  line-height: var(--cipher-type-caption-line-height);
  font-weight: var(--cipher-type-label-font-weight);
}
.frameAction > a:not([data-slot]) {
  color: var(--cipher-link);
  text-decoration: underline;
  text-decoration-thickness: var(--cipher-size-control-border);
  text-underline-offset: var(--cipher-space-3);
}
.frameAction > a:not([data-slot]):hover {
  color: var(--cipher-text2);
  text-decoration-thickness: var(--cipher-space-2);
}
.frameInset {
  min-width: 0;
  background: var(--cipher-surface);
  border: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  border-radius: var(--cipher-frame-inner-radius);
  box-shadow: var(--cipher-shadow-raised);
}

.terminal {
  display: flex;
  flex-direction: column;
  width: 100%;
  min-width: 0;
}
.header {
  justify-content: flex-start;
  gap: var(--cipher-space-4) var(--cipher-space-8);
  padding-inline-start: calc(var(--cipher-space-frame-inline) + var(--cipher-space-frame-title-inline));
  font-family: var(--cipher-type-mono-sm-font-family);
  font-size: var(--cipher-type-mono-sm-font-size);
  line-height: var(--cipher-type-mono-sm-line-height);
  letter-spacing: var(--cipher-type-mono-sm-letter-spacing);
  color: var(--cipher-text2);
}
.identity {
  flex: 1 1 var(--cipher-size-cell-min);
  min-width: 0;
  display: flex;
  align-items: center;
  gap: var(--cipher-space-control-gap);
  font-weight: var(--cipher-type-label-font-weight);
}
.identity > :global([data-slot="icon"]) {
  width: var(--cipher-size-icon-sm);
  height: var(--cipher-size-icon-sm);
  flex: none;
  color: var(--cipher-muted);
}
.label {
  flex: 1;
  min-width: 0;
}
.status {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: var(--cipher-space-6);
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  line-height: var(--cipher-type-caption-line-height);
  color: var(--cipher-muted);
  white-space: nowrap;
}
.dot {
  width: var(--cipher-size-unread);
  height: var(--cipher-size-unread);
  flex: none;
  border-radius: 0;
  background: var(--cipher-faint);
}
.status[data-tone="connected"] .dot {
  background: var(--cipher-ok);
}
.status[data-tone="error"] {
  color: var(--cipher-bad);
}
.status[data-tone="error"] .dot {
  background: var(--cipher-bad);
}
.actions {
  flex: none;
  margin-inline-start: auto;
  display: flex;
  align-items: center;
  gap: var(--cipher-space-control-slot-gap);
}
.body {
  position: relative;
  flex: 1 1 auto;
  min-height: calc(var(--cipher-type-mono-line-height) * 12);
  display: flex;
  padding: var(--cipher-space-surface-inset-sm);
  background: var(--cipher-surface);
}
.screen {
  flex: 1;
  min-width: 0;
  min-height: 0;
  font-family: var(--cipher-type-mono-font-family);
  font-size: var(--cipher-type-mono-font-size);
}
.screen :global(.xterm) {
  height: 100%;
}
.screen :global(.xterm .xterm-viewport) {
  background-color: var(--cipher-surface);
  scrollbar-width: thin;
  scrollbar-color: var(--cipher-scroll-thumb) transparent;
}
.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--cipher-space-8);
  padding: var(--cipher-space-surface-inset);
  text-align: center;
  background: color-mix(in oklab, var(--cipher-surface) 92%, transparent);
}
.overlayTitle {
  margin: 0;
  font-family: var(--cipher-type-title-sm-font-family);
  font-size: var(--cipher-type-title-sm-font-size);
  line-height: var(--cipher-type-title-sm-line-height);
  font-weight: var(--cipher-type-title-sm-font-weight);
  letter-spacing: var(--cipher-type-title-sm-letter-spacing);
  color: var(--cipher-ink);
}
.message {
  margin: 0;
  max-width: var(--cipher-size-measure-prose);
  overflow-wrap: anywhere;
  font-family: var(--cipher-type-body-font-family);
  font-size: var(--cipher-type-body-font-size);
  line-height: var(--cipher-type-body-line-height);
  color: var(--cipher-muted);
}
.overlay > :global([data-cipher-button]) {
  margin-top: var(--cipher-space-4);
}
